func templateParts(input string) (string, string, string, bool, error) {
	s := strings.TrimSpace(input)
	if !strings.Contains(s, "{{") && !strings.Contains(s, "}}") {
		return "", s, "", false, nil
	}
	start := strings.Index(s, "{{")
	end := strings.Index(s, "}}")
	if start < 0 || end < start+2 || strings.Contains(s[:start], "}") || strings.Contains(s[end+2:], "{") || strings.Contains(s[start+2:end], "{") || strings.Contains(s[start+2:end], "}") || strings.Contains(s[end+2:], "}}") || strings.Contains(s[:start], "{{") {
		return "", "", "", false, trace.BadParameter("malformed template usage %q: expected one {{expression}}", input)
	}
	return s[:start], strings.TrimSpace(s[start+2 : end]), s[end+2:], true, nil
}
func NewExpression(input string) (*Expression, error) {
	prefix, middle, suffix, templ, err := templateParts(input)
	if err != nil {
		return nil, err
	}
	if !templ {
		return &Expression{expr: StringLitExpr{middle}, namespace: LiteralNamespace, variable: middle}, nil
	}
	node, err := parse(middle)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if node.Kind() != reflect.String {
		return nil, trace.BadParameter("expression %q does not evaluate to a string", input)
	}
	e := &Expression{expr: node, prefix: prefix, suffix: suffix}
	if v, ok := node.(VarExpr); ok {
		e.namespace = v.Namespace
		e.variable = v.Name
	}
	return e, nil

